\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Little Things - Launchpad Chop Engine\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Turn any section of your REAPER timeline into a playable kit on a {\b Novation Launchpad (MK3)}: capture the audio, slice it and spread the slices across the pads, with matching colors lit on the hardware.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Send the selected timeline range to any pad\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Slice a range into 8, 16, 32 or 64 pads\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Gate, One-Shot and Loop modes, with choke groups\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Playback through auto-configured ReaSamplOmatic5000 instances\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Save and load kits ({\f1 .ltkit})\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Real-time Launchpad LED sync\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Requirements\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\field{\*\fldinst{HYPERLINK "https://github.com/cfillion/reaimgui"}}{\fldrslt{\ul
ReaImGui
}}}
 (available via ReaPack)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Novation Launchpad MK3 (optional, to play on hardware)\sa180\par}
}
